export interface Disposable {
  dispose(): void;
}

export interface CancellationToken {
  readonly isCancellationRequested: boolean;
  onCancellationRequested(listener: () => void): Disposable;
}

export class CancellationTokenSource implements Disposable {
  readonly token: CancellationToken;
  cancel(): void;
  dispose(): void;
}

export const ErrorCodes: {
  readonly ParseError: number;
  readonly InvalidRequest: number;
  readonly MethodNotFound: number;
  readonly InvalidParams: number;
  readonly InternalError: number;
  readonly ServerNotInitialized: number;
  readonly UnknownErrorCode: number;
  readonly RequestCancelled: number;
  readonly ContentModified: number;
};

export class ResponseError<D = unknown> extends Error {
  readonly code: number;
  readonly data?: D;
  constructor(code: number, message: string, data?: D);
  toJson(): { code: number; message: string; data?: D };
}

export class StreamMessageReader implements Disposable {
  constructor(readable: NodeJS.ReadableStream);
  listen(callback: (msg: unknown) => void): Disposable;
  onError(cb: (err: Error) => void): Disposable;
  onClose(cb: () => void): Disposable;
  dispose(): void;
}

export class StreamMessageWriter implements Disposable {
  constructor(writable: NodeJS.WritableStream);
  write(msg: unknown): Promise<void>;
  onError(cb: (err: Error) => void): Disposable;
  onClose(cb: () => void): Disposable;
  end(): void;
  dispose(): void;
}

export interface MessageConnection extends Disposable {
  listen(): void;
  onRequest<P = unknown, R = unknown>(
    method: string | { method: string },
    handler: (params: P, token: CancellationToken) => R | Promise<R>,
  ): Disposable;
  onNotification<P = unknown>(
    method: string | { method: string },
    handler: (params: P) => void | Promise<void>,
  ): Disposable;
  sendRequest<R = unknown>(method: string | { method: string }, params?: unknown): Promise<R>;
  sendNotification(method: string | { method: string }, params?: unknown): Promise<void>;
  onClose(cb: () => void): Disposable;
  onError(cb: (err: Error) => void): Disposable;
  onDispose(cb: () => void): Disposable;
  end(): void;
}

export function createMessageConnection(
  readerOrInput: StreamMessageReader | NodeJS.ReadableStream,
  writerOrOutput: StreamMessageWriter | NodeJS.WritableStream,
): MessageConnection;
